package com.bank.routing.service;

import java.util.logging.Logger;

// Minimum cuts to split a string into palindromic chunks.
public class RoutingSplitService {
    private static final Logger log = Logger.getLogger(RoutingSplitService.class.getName());

    public int minCuts(String routing) {
        int n = routing.length();
        if (n == 0) return 0;
        boolean[][] pal = new boolean[n][n];        // palindrome table
        for (int i = n - 1; i >= 0; i--) {
            pal[i][i] = true;
            for (int j = i + 1; j < n; j++)
                pal[i][j] = routing.charAt(i) == routing.charAt(j)
                            && (j - i < 2 || pal[i + 1][j - 1]);
        }
        int[] cuts = new int[n];                    // cuts[i] = min cuts for prefix 0..i
        for (int i = 0; i < n; i++) {
            if (pal[0][i]) {
                cuts[i] = 0;                        // whole prefix is one palindrome
            } else {
                cuts[i] = i;                        // worst case: cut between every char
                for (int j = 1; j <= i; j++)
                    if (pal[j][i])
                        cuts[i] = Math.min(cuts[i], cuts[j - 1] + 1); // one cut + prior
            }
        }
        final int r = cuts[n - 1];
        log.info(() -> "Min palindromic cuts for " + routing + " = " + r);
        return r;
    }
}
