package com.bank.routing;

import com.bank.routing.service.RoutingSplitService;
import java.util.logging.Logger;

public class RoutingSplitApplication {
    private static final Logger log = Logger.getLogger(RoutingSplitApplication.class.getName());

    public static void main(String[] args) {
        RoutingSplitService service = new RoutingSplitService();
        String routing = "ABACC";
        int cuts = service.minCuts(routing);
        log.info("Minimum chunks minus one for routing " + routing + " is " + cuts);
    }
}
